// Supabase client factory.
// Reads config from environment. Two clients:
//  - anon client: safe for browser/server, honours Row Level Security.
//  - admin client: SERVER ONLY, uses the service-role key and bypasses RLS.
import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = process.env.SUPABASE_URL;
const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY;
const SUPABASE_SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

function requireEnv(name, value) {
  if (!value) throw new Error(`[supabase] missing required env var: ${name}`);
  return value;
}

/** Public/anon client — safe to use in the browser and on the server. */
export function createAnonClient() {
  return createClient(
    requireEnv('SUPABASE_URL', SUPABASE_URL),
    requireEnv('SUPABASE_ANON_KEY', SUPABASE_ANON_KEY),
  );
}

/** Admin client — SERVER ONLY. Uses the service-role key; bypasses RLS. */
export function createAdminClient() {
  return createClient(
    requireEnv('SUPABASE_URL', SUPABASE_URL),
    requireEnv('SUPABASE_SERVICE_ROLE_KEY', SUPABASE_SERVICE_ROLE_KEY),
    { auth: { autoRefreshToken: false, persistSession: false } },
  );
}

// Default shared anon client (lazy) for convenience in app code.
let _anon;
export function supabase() {
  if (!_anon) _anon = createAnonClient();
  return _anon;
}
```

