**`src/supabase/storage.js`**
```javascript
// Supabase Storage wrapper — thin stubs over supabase.storage.
// Bucket defaults to SUPABASE_STORAGE_BUCKET; create the bucket + policies in phase 3.
import { supabase } from './client.js';

const DEFAULT_BUCKET = process.env.SUPABASE_STORAGE_BUCKET || 'customer-files';

export async function uploadFile(path, file, { bucket = DEFAULT_BUCKET, upsert = false } = {}) {
  return supabase().storage.from(bucket).upload(path, file, { upsert });
}

export async function downloadFile(path, { bucket = DEFAULT_BUCKET } = {}) {
  return supabase().storage.from(bucket).download(path);
}

export async function listFiles(prefix = '', { bucket = DEFAULT_BUCKET } = {}) {
  return supabase().storage.from(bucket).list(prefix);
}

export async function removeFiles(paths, { bucket = DEFAULT_BUCKET } = {}) {
  return supabase().storage.from(bucket).remove(paths);
}

export function getPublicUrl(path, { bucket = DEFAULT_BUCKET } = {}) {
  return supabase().storage.from(bucket).getPublicUrl(path);
}

export async function createSignedUrl(path, expiresIn = 3600, { bucket = DEFAULT_BUCKET } = {}) {
  return supabase().storage.from(bucket).createSignedUrl(path, expiresIn);
}
```

